import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let q = conc.Mutex(0)
    let notZero = conc.Cond(q)
    scope {
        let waiter = task effect io {
            notZero.wait(|v| v > 0)
            io.println("woken")
        }
        let setter = task effect io {
            let _ = q.set(1)
            let _ = notZero.signal()
            io.println("signaled")
        }
        let _ = waiter.await()
        let _ = setter.await()
    }
    return Ok(())
}
